-- Read-only post-007 inspection, before any draft creation or catalog/role edits.
-- Baselines are from the user-supplied 16-row preflight CSV (28).
-- Never calls mutation RPCs or nextval/setval. Configuration evidence only.
begin transaction isolation level repeatable read, read only;
with
expected_functions(signature,result_type,definer,volatility,body_md5,arg_names) as (values
 ('batool_catalog_internal.require_owner()','void',false,'v','3762d0f92d524f6bdd808a30a03975e7',array[]::text[]),
 ('batool_catalog_internal.validate_fields(text,text,integer,jsonb)','void',false,'v','be4e49a344b81fec86a51d0b9a84cf9e',array['p_name','p_description','p_price','p_stocks']::text[]),
 ('batool_catalog_internal.product_json(integer)','jsonb',false,'v','43da535969f6e6a8c129a870aa881a0b',array['p_id']::text[]),
 ('batool_catalog_internal.guard_product()','trigger',false,'v','62268f61f1086e3ec5a71f9dbeb5a2d3',array[]::text[]),
 ('batool_catalog_internal.reject_truncate()','trigger',false,'v','9eb2f4041638d9542cb90cd5cfb77697',array[]::text[]),
 ('batool_catalog_internal.complete_draft()','trigger',false,'v','08ceae75f1204ff70027127fc04979a8',array[]::text[]),
 ('batool_catalog_internal.guard_variant_identity()','trigger',false,'v','12257e0348481f863634b729b1fb5bcc',array[]::text[]),
 ('public.owner_create_product_draft(uuid,text,text,integer,jsonb)','jsonb',true,'v','5f8a94e72e92226464cb35c564b30cd9',array['p_request_key','p_name','p_description','p_price_minor','p_stocks']::text[]),
 ('public.owner_save_catalog_product(integer,integer,text,text,integer,boolean,jsonb,text,text,text,boolean)','jsonb',true,'v','21f7b26c62748bddf8133bcf3700af1d',array['p_product_id','p_expected_revision','p_name','p_description','p_price_minor','p_active','p_stocks','p_subcategory','p_color','p_tag','p_archived']::text[]),
 ('public.owner_update_catalog_product(integer,integer,text,text,integer,boolean,jsonb)','jsonb',true,'v','ba69a976e6fa90daa55d95914bfbcd2b',array['p_product_id','p_expected_revision','p_name','p_description','p_price_minor','p_active','p_stocks']::text[]),
 ('public.batool_image_upload_path(text,uuid)','boolean',false,'s','3b96fee1467ebbbc393c681da9e36306',array['p_name','p_user']::text[]),
 ('public.owner_attach_product_image(integer,integer,text,text)','jsonb',true,'v','7dbfb2ebcc71209e8af728c8ecee50c6',array['p_product_id','p_expected_revision','p_image_path','p_alt']::text[]),
 ('public.batool_catalog_updated_at()','trigger',false,'v','077bb7aa35a4fed76f447b242607c205',array[]::text[]),
 ('public.batool_product_revision()','trigger',false,'v','4aba5178a32335ffddbb461296ffd6d9',array[]::text[]),
 ('public.batool_variant_revision()','trigger',true,'v','c02a456d0258bb1d97ac16a161054d49',array[]::text[]),
 ('public.batool_catalog_owner()','boolean',true,'s','a87175634ff5ebbfe49e2fcbb3353df8',array[]::text[]),
 ('public.register_product_image_asset(integer,uuid,text,integer,integer,integer,text)','void',true,'v','7eae250a9560dc519b2ad33a84aad6e5',array['p_product_id','p_user_id','p_image_path','p_width','p_height','p_byte_size','p_sha256'])),
function_report as (
 select e.signature,p.oid is not null as present,
   coalesce(p.prorettype::regtype::text=e.result_type and p.prosecdef=e.definer
     and p.provolatile::text=e.volatility and p.prokind='f' and not p.proretset
     and coalesce(p.proargnames,array[]::text[])=e.arg_names
     and p.proconfig=array['search_path=""'],false) as contract_matches,
   coalesce(md5(btrim(regexp_replace(p.prosrc,'[[:space:]]+',' ','g')))=e.body_md5,false) as source_matches,
   pg_get_userbyid(p.proowner) as owner,p.proacl::text as acl,
   has_function_privilege('anon',p.oid,'EXECUTE') as anon_execute,
   has_function_privilege('authenticated',p.oid,'EXECUTE') as authenticated_execute,
   has_function_privilege('service_role',p.oid,'EXECUTE') as service_execute,
   exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.grantee=0 and a.privilege_type='EXECUTE') as public_execute
 from expected_functions e left join pg_proc p on p.oid=to_regprocedure(e.signature)),
baseline as (
 select jsonb_build_object(
   'products_count',(select count(*) from public.products),
   'products_md5',(select md5(coalesce(jsonb_agg(to_jsonb(p)-'draft_managed'-'archived' order by id)::text,'[]')) from public.products p),
   'variants_count',(select count(*) from public.product_variants),
   'variants_md5',(select md5(coalesce(jsonb_agg(to_jsonb(v) order by product_id,size)::text,'[]')) from public.product_variants v),
   'roles_count',(select count(*) from public.dashboard_roles),
   'roles_md5',(select md5(coalesce(jsonb_agg(to_jsonb(r) order by user_id)::text,'[]')) from public.dashboard_roles r),
   'image_receipts_count',(select count(*) from public.product_image_assets),
   'image_receipts_md5',(select md5(coalesce(jsonb_agg(to_jsonb(a) order by image_path)::text,'[]')) from public.product_image_assets a)) as actual),
policies as (
 select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) as actual from pg_policies p where
   (schemaname='public' and tablename in ('products','product_variants','product_image_assets','dashboard_roles'))
   or (schemaname='storage' and tablename='objects')),
browser_privileges as (
 select jsonb_agg(jsonb_build_object('role',r.rolname,'superuser',r.rolsuper,'bypassrls',r.rolbypassrls,
   'service_member',pg_has_role(r.oid,'service_role','MEMBER'),
   'inherited_roles',coalesce((select jsonb_agg(parent.rolname order by parent.rolname) from pg_roles parent
     where parent.oid<>r.oid and pg_has_role(r.oid,parent.oid,'USAGE')),'[]'::jsonb),
   'tables',(select jsonb_agg(jsonb_build_object('table',t,'select',has_table_privilege(r.oid,t,'SELECT'),
     'insert',has_table_privilege(r.oid,t,'INSERT'),'update',has_table_privilege(r.oid,t,'UPDATE'),
     'delete',has_table_privilege(r.oid,t,'DELETE'),'truncate',has_table_privilege(r.oid,t,'TRUNCATE'),
     'column_insert',has_any_column_privilege(r.oid,t,'INSERT'),'column_update',has_any_column_privilege(r.oid,t,'UPDATE')) order by t)
     from unnest(array['public.products','public.product_variants','public.product_image_assets','public.dashboard_roles']) tables(t))) order by r.rolname) as actual
 from pg_roles r where r.rolname in ('anon','authenticated')),
retained_constraints as (
 select jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,'type',c.contype,
   'validated',c.convalidated,'index_valid',i.indisvalid,'definition',pg_get_constraintdef(c.oid)) order by c.conrelid::regclass::text,c.conname) as actual
 from pg_constraint c left join pg_index i on i.indexrelid=c.conindid where c.conrelid in
   ('public.products'::regclass,'public.product_variants'::regclass,'public.product_image_assets'::regclass,'public.dashboard_roles'::regclass,'public.order_items'::regclass)
   -- Constraint triggers also create pg_constraint entries. They are new in 007,
   -- and their definitions/deferral are inspected in 07_triggers above.
   and c.conname not in ('product_image_asset_path','products_permanent_ids','products_draft_identity','products_slug_length','products_tag_length',
     'products_complete_draft','variants_complete_draft')),
results(check_name,expected,actual) as (
 select '00_context','read_only on; role postgres',jsonb_build_object('read_only',current_setting('transaction_read_only'),'role',current_user)
 union all select '01_baseline','matches_preflight true; unchanged catalog, variants, sole role mapping and receipts',
   jsonb_build_object('matches_preflight',actual='{"roles_md5":"0c1b648c767615366a121b0be30ad1e8","roles_count":1,"products_md5":"1089dfcd021ab052a75674ba0e6f698e","variants_md5":"058486c5ccd606ae38a84cc9cc933ea5","products_count":6,"variants_count":24,"image_receipts_md5":"d751713988987e9331980363e24189ce","image_receipts_count":0}'::jsonb,'current',actual) from baseline
 union all select '02_product_columns','draft_managed/archived boolean NOT NULL default false; other four columns nullable; id default null/identity empty',
   (select jsonb_agg(jsonb_build_object('column',a.attname,'type',format_type(a.atttypid,a.atttypmod),
     'not_null',a.attnotnull,'identity',a.attidentity,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attname)
    from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
    where a.attrelid='public.products'::regclass and not a.attisdropped
      and a.attname in ('id','draft_managed','archived','image_slug','subcategory','color','tag'))
 union all select '03_sequence','integer; min/start 12; max 2147483647; increment/cache 1; cycle false; last_value 12/is_called false (before any attempts)',
   (select jsonb_build_object('owner',pg_get_userbyid(c.relowner),'type',format_type(s.seqtypid,null),
     'min',s.seqmin,'max',s.seqmax,'start',s.seqstart,'increment',s.seqincrement,'cache',s.seqcache,'cycle',s.seqcycle,
     'last_value',(select last_value from batool_catalog_internal.product_ids),
     'is_called',(select is_called from batool_catalog_internal.product_ids))
    from pg_sequence s join pg_class c on c.oid=s.seqrelid where s.seqrelid='batool_catalog_internal.product_ids'::regclass)
 union all select '04_private_objects','schema/table/sequence owner postgres; RLS true; request_count 0; policies []; every role privilege false',
   jsonb_build_object('schema_owner',(select pg_get_userbyid(nspowner) from pg_namespace where nspname='batool_catalog_internal'),
     'table_owner',(select pg_get_userbyid(relowner) from pg_class where oid='batool_catalog_internal.creation_requests'::regclass),
     'rls',(select relrowsecurity from pg_class where oid='batool_catalog_internal.creation_requests'::regclass),
     'request_count',(select count(*) from batool_catalog_internal.creation_requests),
     'policies',coalesce((select jsonb_agg(to_jsonb(p)) from pg_policies p where schemaname='batool_catalog_internal'),'[]'::jsonb),
     'role_privileges',(select jsonb_agg(jsonb_build_object('role',r,'schema_usage',has_schema_privilege(r,'batool_catalog_internal','USAGE'),
       'schema_create',has_schema_privilege(r,'batool_catalog_internal','CREATE'),
       'sequence_any',has_sequence_privilege(r,'batool_catalog_internal.product_ids','USAGE,SELECT,UPDATE'),
       'table_any',has_table_privilege(r,'batool_catalog_internal.creation_requests','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),
       'column_select',has_any_column_privilege(r,'batool_catalog_internal.creation_requests','SELECT'),
       'column_insert',has_any_column_privilege(r,'batool_catalog_internal.creation_requests','INSERT'),
       'column_update',has_any_column_privilege(r,'batool_catalog_internal.creation_requests','UPDATE'),
       'column_references',has_any_column_privilege(r,'batool_catalog_internal.creation_requests','REFERENCES')) order by r)
       from unnest(array['anon','authenticated','service_role']) roles(r)))
 union all select '05_function_contracts','17 functions; all present/contract_matches/source_matches true; all owners postgres. Four Owner RPCs: auth true, anon/service/PUBLIC false. All seven internal functions: every execute false. Registration: service only',
   (select jsonb_agg(to_jsonb(f) order by signature) from function_report f)
 union all select '06_unexpected_functions','[]; no extra internal functions or overloads of inspected public functions',
   coalesce((select jsonb_agg(p.oid::regprocedure::text order by p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace
     where (n.nspname='batool_catalog_internal' or (n.nspname='public' and p.proname in
       ('owner_create_product_draft','owner_save_catalog_product','owner_update_catalog_product','owner_attach_product_image',
        'batool_catalog_owner','batool_image_upload_path','batool_catalog_updated_at','batool_product_revision','batool_variant_revision','register_product_image_asset')))
       and not exists(select 1 from expected_functions e where to_regprocedure(e.signature)=p.oid)),'[]'::jsonb)
 union all select '07_triggers','10 enabled O triggers; complete_draft pair deferrable/initially deferred true; review full definitions',
   (select jsonb_agg(jsonb_build_object('table',tgrelid::regclass::text,'name',tgname,'enabled',tgenabled,
     'deferrable',tgdeferrable,'initially_deferred',tginitdeferred,'definition',pg_get_triggerdef(oid)) order by tgrelid::regclass::text,tgname)
    from pg_trigger where tgrelid in ('public.products'::regclass,'public.product_variants'::regclass) and not tgisinternal)
 union all select '08_constraints','retained_matches_preflight true; 9 added/replaced constraints validated; review reserved ID, draft, slug/tag, strict image binding and 4 request PK/UNIQUE/FKs',
   jsonb_build_object('retained_matches_preflight',(select actual='[{"name":"dashboard_roles_pkey","type":"p","table":"dashboard_roles","validated":true,"definition":"PRIMARY KEY (user_id)","index_valid":true},{"name":"dashboard_roles_role_check","type":"c","table":"dashboard_roles","validated":true,"definition":"CHECK ((role = ANY (ARRAY[''owner''::text, ''partner''::text])))","index_valid":null},{"name":"dashboard_roles_user_id_fkey","type":"f","table":"dashboard_roles","validated":true,"definition":"FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE","index_valid":true},{"name":"order_items_complete","type":"t","table":"order_items","validated":true,"definition":"TRIGGER DEFERRABLE INITIALLY DEFERRED","index_valid":null},{"name":"order_items_line_number_check","type":"c","table":"order_items","validated":true,"definition":"CHECK ((line_number > 0))","index_valid":null},{"name":"order_items_order_id_fkey","type":"f","table":"order_items","validated":true,"definition":"FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE RESTRICT","index_valid":true},{"name":"order_items_order_id_product_id_selected_size_key","type":"u","table":"order_items","validated":true,"definition":"UNIQUE (order_id, product_id, selected_size)","index_valid":true},{"name":"order_items_pkey","type":"p","table":"order_items","validated":true,"definition":"PRIMARY KEY (order_id, line_number)","index_valid":true},{"name":"order_items_product_id_selected_size_fkey","type":"f","table":"order_items","validated":true,"definition":"FOREIGN KEY (product_id, selected_size) REFERENCES product_variants(product_id, size) ON DELETE RESTRICT","index_valid":true},{"name":"order_items_product_name_check","type":"c","table":"order_items","validated":true,"definition":"CHECK ((((char_length(btrim(product_name)) >= 1) AND (char_length(btrim(product_name)) <= 120)) AND (product_name ~ ''[^[:space:]]''::text) AND (product_name !~ ''[[:cntrl:]]''::text)))","index_valid":null},{"name":"order_items_quantity_check","type":"c","table":"order_items","validated":true,"definition":"CHECK ((quantity > 0))","index_valid":null},{"name":"order_items_selected_size_check","type":"c","table":"order_items","validated":true,"definition":"CHECK ((selected_size = ANY (ARRAY[''S''::text, ''M''::text, ''L''::text, ''XL''::text])))","index_valid":null},{"name":"order_items_unit_price_minor_check","type":"c","table":"order_items","validated":true,"definition":"CHECK ((unit_price_minor >= 0))","index_valid":null},{"name":"product_image_assets_byte_size_check","type":"c","table":"product_image_assets","validated":true,"definition":"CHECK (((byte_size >= 1) AND (byte_size <= 5242880)))","index_valid":null},{"name":"product_image_assets_height_check","type":"c","table":"product_image_assets","validated":true,"definition":"CHECK (((height >= 384) AND (height <= 1600)))","index_valid":null},{"name":"product_image_assets_pkey","type":"p","table":"product_image_assets","validated":true,"definition":"PRIMARY KEY (image_path)","index_valid":true},{"name":"product_image_assets_product_id_fkey","type":"f","table":"product_image_assets","validated":true,"definition":"FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT","index_valid":true},{"name":"product_image_assets_sha256_check","type":"c","table":"product_image_assets","validated":true,"definition":"CHECK ((sha256 ~ ''^[0-9a-f]{64}$''::text))","index_valid":null},{"name":"product_image_assets_uploaded_by_fkey","type":"f","table":"product_image_assets","validated":true,"definition":"FOREIGN KEY (uploaded_by) REFERENCES auth.users(id) ON DELETE SET NULL","index_valid":true},{"name":"product_image_assets_width_check","type":"c","table":"product_image_assets","validated":true,"definition":"CHECK (((width >= 384) AND (width <= 1600)))","index_valid":null},{"name":"product_variants_pkey","type":"p","table":"product_variants","validated":true,"definition":"PRIMARY KEY (product_id, size)","index_valid":true},{"name":"product_variants_product_id_fkey","type":"f","table":"product_variants","validated":true,"definition":"FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT","index_valid":true},{"name":"product_variants_size_check","type":"c","table":"product_variants","validated":true,"definition":"CHECK ((size = ANY (ARRAY[''S''::text, ''M''::text, ''L''::text, ''XL''::text])))","index_valid":null},{"name":"product_variants_stock_quantity_check","type":"c","table":"product_variants","validated":true,"definition":"CHECK ((stock_quantity >= 0))","index_valid":null},{"name":"products_card_zoom_check","type":"c","table":"products","validated":true,"definition":"CHECK (((card_zoom >= (1)::numeric) AND (card_zoom <= (3)::numeric)))","index_valid":null},{"name":"products_category_check","type":"c","table":"products","validated":true,"definition":"CHECK ((category = ''Stitched''::text))","index_valid":null},{"name":"products_color_check","type":"c","table":"products","validated":true,"definition":"CHECK ((color ~ ''^#[0-9A-Fa-f]{6}$''::text))","index_valid":null},{"name":"products_currency_check","type":"c","table":"products","validated":true,"definition":"CHECK ((currency = ''PKR''::text))","index_valid":null},{"name":"products_description_check","type":"c","table":"products","validated":true,"definition":"CHECK ((length(TRIM(BOTH FROM description)) > 0))","index_valid":null},{"name":"products_edit_revision_check","type":"c","table":"products","validated":true,"definition":"CHECK ((edit_revision > 0))","index_valid":null},{"name":"products_editor_description_length","type":"c","table":"products","validated":true,"definition":"CHECK ((((char_length(btrim(description)) >= 1) AND (char_length(btrim(description)) <= 2000)) AND (description ~ ''[^[:space:]]''::text)))","index_valid":null},{"name":"products_editor_name_length","type":"c","table":"products","validated":true,"definition":"CHECK ((((char_length(btrim(name)) >= 1) AND (char_length(btrim(name)) <= 120)) AND (name ~ ''[^[:space:]]''::text)))","index_valid":null},{"name":"products_id_check","type":"c","table":"products","validated":true,"definition":"CHECK ((id >= 0))","index_valid":null},{"name":"products_image_slug_check","type":"c","table":"products","validated":true,"definition":"CHECK ((image_slug = ANY (ARRAY[''gulnaar''::text, ''meher''::text, ''saba''::text, ''noor''::text, ''mira''::text, ''amanah''::text, ''layal''::text, ''zeenat''::text])))","index_valid":null},{"name":"products_main_image_path_fkey","type":"f","table":"products","validated":true,"definition":"FOREIGN KEY (main_image_path) REFERENCES product_image_assets(image_path) ON DELETE RESTRICT","index_valid":true},{"name":"products_main_image_valid","type":"c","table":"products","validated":true,"definition":"CHECK ((((main_image_path IS NULL) AND (main_image_width IS NULL) AND (main_image_height IS NULL) AND (image_alt IS NULL)) OR ((main_image_path IS NOT NULL) AND (main_image_width IS NOT NULL) AND (main_image_height IS NOT NULL) AND (image_alt IS NOT NULL) AND ((main_image_width >= 384) AND (main_image_width <= 1600)) AND ((main_image_height >= 384) AND (main_image_height <= 1600)) AND ((char_length(btrim(image_alt)) >= 1) AND (char_length(btrim(image_alt)) <= 240)) AND (image_alt ~ ''[^[:space:]]''::text) AND (image_alt !~ ''[[:cntrl:]]''::text) AND (main_image_path ~ ((''^products/''::text || (id)::text) || ''/[0-9a-f-]{36}/[0-9a-f-]{36}/main\\.webp$''::text)))))","index_valid":null},{"name":"products_name_check","type":"c","table":"products","validated":true,"definition":"CHECK ((length(TRIM(BOTH FROM name)) > 0))","index_valid":null},{"name":"products_piece_count_check","type":"c","table":"products","validated":true,"definition":"CHECK ((piece_count = 3))","index_valid":null},{"name":"products_pkey","type":"p","table":"products","validated":true,"definition":"PRIMARY KEY (id)","index_valid":true},{"name":"products_price_minor_check","type":"c","table":"products","validated":true,"definition":"CHECK ((price_minor >= 0))","index_valid":null},{"name":"products_slug_check","type":"c","table":"products","validated":true,"definition":"CHECK ((slug ~ ''^[a-z0-9]+(-[a-z0-9]+)*$''::text))","index_valid":null},{"name":"products_slug_key","type":"u","table":"products","validated":true,"definition":"UNIQUE (slug)","index_valid":true},{"name":"products_sort_order_check","type":"c","table":"products","validated":true,"definition":"CHECK ((sort_order >= 0))","index_valid":null},{"name":"products_subcategory_check","type":"c","table":"products","validated":true,"definition":"CHECK ((subcategory = ANY (ARRAY[''Daily Pret''::text, ''Festive Edit''::text, ''Luxury Formals''::text])))","index_valid":null},{"name":"products_tag_check","type":"c","table":"products","validated":true,"definition":"CHECK ((length(TRIM(BOTH FROM tag)) > 0))","index_valid":null}]'::jsonb from retained_constraints),
     'added_or_replaced',(select jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,
       'validated',c.convalidated,'index_valid',i.indisvalid,'definition',pg_get_constraintdef(c.oid)) order by c.conrelid::regclass::text,c.conname)
       from pg_constraint c left join pg_index i on i.indexrelid=c.conindid where c.conrelid='batool_catalog_internal.creation_requests'::regclass
       or (c.conrelid='public.products'::regclass and c.conname in ('products_permanent_ids','products_draft_identity','products_slug_length','products_tag_length'))
       or (c.conrelid='public.product_image_assets'::regclass and c.conname='product_image_asset_path')))
 union all select '09_policies_and_browser_privileges','both matches_preflight true; existing RLS SELECT/Storage guards and effective table/column grants unchanged',
   jsonb_build_object('policies_match_preflight',(select actual='[{"cmd":"SELECT","qual":"((user_id = ( SELECT auth.uid() AS uid)) AND (COALESCE(( SELECT (auth.jwt() ->> ''is_anonymous''::text)), ''false''::text) <> ''true''::text))","roles":["authenticated"],"tablename":"dashboard_roles","permissive":"PERMISSIVE","policyname":"dashboard_role_read_self","schemaname":"public","with_check":null},{"cmd":"SELECT","qual":"batool_catalog_owner()","roles":["authenticated"],"tablename":"product_image_assets","permissive":"PERMISSIVE","policyname":"owner_image_assets_read","schemaname":"public","with_check":null},{"cmd":"SELECT","qual":"(EXISTS ( SELECT 1\n   FROM dashboard_roles r\n  WHERE ((r.user_id = ( SELECT auth.uid() AS uid)) AND (r.role = ''owner''::text))))","roles":["authenticated"],"tablename":"product_variants","permissive":"PERMISSIVE","policyname":"owner_variants_read","schemaname":"public","with_check":null},{"cmd":"SELECT","qual":"(active AND (EXISTS ( SELECT 1\n   FROM products p\n  WHERE ((p.id = product_variants.product_id) AND p.active))))","roles":["anon"],"tablename":"product_variants","permissive":"PERMISSIVE","policyname":"storefront_variants_read","schemaname":"public","with_check":null},{"cmd":"SELECT","qual":"(EXISTS ( SELECT 1\n   FROM dashboard_roles r\n  WHERE ((r.user_id = ( SELECT auth.uid() AS uid)) AND (r.role = ''owner''::text))))","roles":["authenticated"],"tablename":"products","permissive":"PERMISSIVE","policyname":"owner_products_read","schemaname":"public","with_check":null},{"cmd":"SELECT","qual":"active","roles":["anon"],"tablename":"products","permissive":"PERMISSIVE","policyname":"storefront_products_read","schemaname":"public","with_check":null},{"cmd":"DELETE","qual":"(bucket_id <> ALL (ARRAY[''product-image-uploads''::text, ''product-images''::text]))","roles":["public"],"tablename":"objects","permissive":"RESTRICTIVE","policyname":"batool_images_delete_guard","schemaname":"storage","with_check":null},{"cmd":"INSERT","qual":null,"roles":["public"],"tablename":"objects","permissive":"RESTRICTIVE","policyname":"batool_images_insert_guard","schemaname":"storage","with_check":"((bucket_id <> ALL (ARRAY[''product-image-uploads''::text, ''product-images''::text])) OR ((bucket_id = ''product-image-uploads''::text) AND batool_catalog_owner() AND (owner_id = (( SELECT auth.uid() AS uid))::text) AND batool_image_upload_path(name, ( SELECT auth.uid() AS uid))))"},{"cmd":"SELECT","qual":"((bucket_id <> ALL (ARRAY[''product-image-uploads''::text, ''product-images''::text])) OR ((bucket_id = ''product-image-uploads''::text) AND batool_catalog_owner() AND (owner_id = (( SELECT auth.uid() AS uid))::text) AND batool_image_upload_path(name, ( SELECT auth.uid() AS uid))))","roles":["public"],"tablename":"objects","permissive":"RESTRICTIVE","policyname":"batool_images_read_guard","schemaname":"storage","with_check":null},{"cmd":"UPDATE","qual":"(bucket_id <> ALL (ARRAY[''product-image-uploads''::text, ''product-images''::text]))","roles":["public"],"tablename":"objects","permissive":"RESTRICTIVE","policyname":"batool_images_update_guard","schemaname":"storage","with_check":"(bucket_id <> ALL (ARRAY[''product-image-uploads''::text, ''product-images''::text]))"},{"cmd":"INSERT","qual":null,"roles":["authenticated"],"tablename":"objects","permissive":"PERMISSIVE","policyname":"batool_owner_image_upload","schemaname":"storage","with_check":"((bucket_id = ''product-image-uploads''::text) AND batool_catalog_owner() AND (owner_id = (( SELECT auth.uid() AS uid))::text) AND batool_image_upload_path(name, ( SELECT auth.uid() AS uid)))"},{"cmd":"SELECT","qual":"((bucket_id = ''product-image-uploads''::text) AND batool_catalog_owner() AND (owner_id = (( SELECT auth.uid() AS uid))::text) AND batool_image_upload_path(name, ( SELECT auth.uid() AS uid)))","roles":["authenticated"],"tablename":"objects","permissive":"PERMISSIVE","policyname":"batool_owner_image_upload_read","schemaname":"storage","with_check":null}]'::jsonb from policies),
     'browser_privileges_match_preflight',(select actual='[{"role":"anon","tables":[{"table":"public.dashboard_roles","delete":false,"insert":false,"select":false,"update":false,"truncate":false,"column_insert":false,"column_update":false},{"table":"public.product_image_assets","delete":false,"insert":false,"select":false,"update":false,"truncate":false,"column_insert":false,"column_update":false},{"table":"public.product_variants","delete":false,"insert":false,"select":true,"update":false,"truncate":false,"column_insert":false,"column_update":false},{"table":"public.products","delete":false,"insert":false,"select":true,"update":false,"truncate":false,"column_insert":false,"column_update":false}],"bypassrls":false,"superuser":false,"service_member":false,"inherited_roles":[]},{"role":"authenticated","tables":[{"table":"public.dashboard_roles","delete":false,"insert":false,"select":true,"update":false,"truncate":false,"column_insert":false,"column_update":false},{"table":"public.product_image_assets","delete":false,"insert":false,"select":true,"update":false,"truncate":false,"column_insert":false,"column_update":false},{"table":"public.product_variants","delete":false,"insert":false,"select":true,"update":false,"truncate":false,"column_insert":false,"column_update":false},{"table":"public.products","delete":false,"insert":false,"select":true,"update":false,"truncate":false,"column_insert":false,"column_update":false}],"bypassrls":false,"superuser":false,"service_member":false,"inherited_roles":[]}]'::jsonb from browser_privileges),
     'public_rls',(select jsonb_agg(jsonb_build_object('table',oid::regclass::text,'rls',relrowsecurity) order by relname)
       from pg_class where oid in ('public.products'::regclass,'public.product_variants'::regclass,'public.product_image_assets'::regclass,'public.dashboard_roles'::regclass)))
 union all select '10_retained_identity_and_flags','IDs [0,2,3,7,8,11]; draft_managed/archived false; reserved IDs 0; sole Owner mapping still backed by Auth',
   jsonb_build_object('products',(select jsonb_agg(jsonb_build_object('id',id,'slug',slug,'image_slug',image_slug,'active',active,
     'draft_managed',draft_managed,'archived',archived) order by id) from public.products),
     'reserved_ids',(select count(*) from public.products where id in (9,10)),
     'owner_accounts_present',exists(select 1 from public.dashboard_roles r join auth.users u on u.id=r.user_id where r.role='owner'))
)
select check_name,expected,actual from results order by check_name;
rollback;
